insert into public.units (id, name, description, sort_order) values ('pathology', 'Pathology', 'Sample spotter questions. The pictures are placeholder drawings, to be replaced with real photographs.', 2)
insert into public.topics (id, unit_id, name, sort_order) values ('path-haematology-spotters', 'pathology', 'Haematology spotters', 0)
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('path-haem-001', 'path-haematology-spotters', 'mcq', 'What abnormal red cell shape is shown in this blood film?', '["Sickle cells", "Target cells", "Spherocytes", "Schistocytes", "Elliptocytes"]'::jsonb, 'Sickle cells', '[]'::jsonb, 'The elongated, crescent-shaped cells are sickle cells (drepanocytes). Haemoglobin S polymerises when deoxygenated and distorts the red cell. They are seen in sickle cell disease, not in the trait under normal conditions.', 'seed/sickle_cells.png', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('path-haem-002', 'path-haematology-spotters', 'saq', 'Name the red cells shown, which have a dark spot in the middle of the pale centre.', '[]'::jsonb, 'Target cells', '["Codocytes", "Target cell", "Codocyte"]'::jsonb, 'Target cells (codocytes) have extra membrane relative to their haemoglobin content, so haemoglobin collects in the centre like a bullseye. They are seen in thalassaemia, liver disease, haemoglobin C disease and after splenectomy.', 'seed/target_cells.png', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('path-haem-003', 'path-haematology-spotters', 'mcq', 'The red cells here are stacked like piles of coins. This appearance is most typical of:', '["Multiple myeloma", "Iron deficiency anaemia", "Sickle cell disease", "G6PD deficiency", "Hereditary spherocytosis"]'::jsonb, 'Multiple myeloma', '[]'::jsonb, 'This is rouleaux formation. High levels of plasma proteins such as the paraprotein of multiple myeloma (or fibrinogen in inflammation) cancel the negative charge that normally keeps red cells apart. It is also the reason the ESR is raised.', 'seed/rouleaux.png', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('path-haem-004', 'path-haematology-spotters', 'mcq', 'The fragmented red cells shown are schistocytes. Their presence indicates:', '["Microangiopathic haemolytic anaemia", "Megaloblastic anaemia", "Thalassaemia trait", "Aplastic anaemia", "Polycythaemia vera"]'::jsonb, 'Microangiopathic haemolytic anaemia', '[]'::jsonb, 'Schistocytes are red cells cut into fragments (triangles and helmet shapes) as they are forced through fibrin strands or damaged valves. They point to microangiopathic haemolysis: DIC, TTP, haemolytic uraemic syndrome, or a mechanical heart valve.', 'seed/schistocytes.png', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('path-haem-005', 'path-haematology-spotters', 'saq', 'The neutrophil in the centre has six nuclear lobes. Deficiency of which vitamin classically causes this?', '[]'::jsonb, 'Vitamin B12', '["B12", "Cobalamin", "Folate", "Folic acid", "Vitamin B12 or folate", "B12 or folate", "Vitamin B9"]'::jsonb, 'A neutrophil with six or more lobes is hypersegmented. It is an early sign of megaloblastic anaemia, caused by vitamin B12 or folate deficiency, in which DNA synthesis is impaired while the cytoplasm matures normally.', 'seed/hypersegmented_neutrophil.png', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('path-haem-006', 'path-haematology-spotters', 'mcq', 'Small ring forms with a red dot are seen inside several red cells. What is the most likely diagnosis?', '["Malaria", "Sickle cell disease", "Iron deficiency anaemia", "Infectious mononucleosis", "Lead poisoning"]'::jsonb, 'Malaria', '[]'::jsonb, 'The rings are trophozoites of Plasmodium: a blue ring of cytoplasm with a red chromatin dot ("signet ring" form). Thick and thin blood films remain the standard for diagnosing malaria and counting the parasites.', 'seed/malaria_rings.png', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('path-haem-007', 'path-haematology-spotters', 'saq', 'What are the red rod-shaped inclusions in the cytoplasm of this blast cell called?', '[]'::jsonb, 'Auer rods', '["Auer rod", "Auer bodies", "Auer body"]'::jsonb, 'Auer rods are needle-like fused granules found only in myeloid blasts. Finding them confirms acute myeloid leukaemia rather than acute lymphoblastic leukaemia; they are numerous in acute promyelocytic leukaemia.', 'seed/auer_rods.png', 'seed')
insert into public.topics (id, unit_id, name, sort_order) values ('path-histology-spotters', 'pathology', 'Histopathology spotters', 1)
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('path-hist-001', 'path-histology-spotters', 'mcq', 'The large cell with two mirror-image nuclei ("owl eyes") is characteristic of:', '["Hodgkin lymphoma", "Burkitt lymphoma", "Chronic myeloid leukaemia", "Multiple myeloma", "Infectious mononucleosis"]'::jsonb, 'Hodgkin lymphoma', '[]'::jsonb, 'This is a Reed-Sternberg cell: a large cell with two nuclei or lobes, each with a big red nucleolus, in a background of small lymphocytes. It is the neoplastic cell of classical Hodgkin lymphoma and is positive for CD15 and CD30.', 'seed/reed_sternberg.png', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('path-hist-002', 'path-histology-spotters', 'mcq', 'The cells shown have a large mucin vacuole pushing the nucleus to one side. They are typical of which tumour?', '["Diffuse-type gastric adenocarcinoma", "Squamous cell carcinoma of the oesophagus", "Hepatocellular carcinoma", "Carcinoid tumour", "Gastrointestinal stromal tumour"]'::jsonb, 'Diffuse-type gastric adenocarcinoma', '[]'::jsonb, 'These are signet ring cells. Mucin fills the cytoplasm and flattens the nucleus against the cell membrane. They are the hallmark of diffuse-type gastric adenocarcinoma, which infiltrates the stomach wall (linitis plastica) and can spread to the ovaries as Krukenberg tumours.', 'seed/signet_ring_cells.png', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('path-hist-003', 'path-histology-spotters', 'saq', 'These liver cells contain large clear fat vacuoles that push the nucleus aside. Name this change.', '[]'::jsonb, 'Steatosis', '["Fatty change", "Fatty liver", "Hepatic steatosis", "Macrovesicular steatosis", "Fatty liver disease"]'::jsonb, 'This is macrovesicular steatosis (fatty change): triglyceride accumulates as one large droplet per hepatocyte. The common causes are alcohol, obesity and diabetes (non-alcoholic fatty liver disease). It is reversible if the cause is removed.', 'seed/steatosis.png', 'seed')
insert into public.units (id, name, description, sort_order) values ('pharmacology', 'Pharmacology', 'Starter test data. Subtopics and questions will be replaced with the full unit outline.', 1)
insert into public.topics (id, unit_id, name, sort_order) values ('pharm-general-principles', 'pharmacology', 'General principles', 0)
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-gp-001', 'pharm-general-principles', 'mcq', 'First-pass metabolism of an orally administered drug takes place mainly in which organ?', '["Liver", "Kidney", "Lungs", "Spleen", "Pancreas"]'::jsonb, 'Liver', '[]'::jsonb, 'Drugs absorbed from the gut travel in the portal vein to the liver before reaching the systemic circulation. Hepatic enzymes can metabolise a large fraction on this first pass (the gut wall contributes a little), which lowers oral bioavailability. The kidneys mainly excrete drugs rather than metabolise them.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-gp-002', 'pharm-general-principles', 'saq', 'What term describes the fraction of an administered dose that reaches the systemic circulation unchanged?', '[]'::jsonb, 'Bioavailability', '[]'::jsonb, 'Bioavailability (F) is the proportion of a dose that reaches the systemic circulation in active form. It is 100% for an intravenous dose and lower for oral doses because of incomplete absorption and first-pass metabolism.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-gp-003', 'pharm-general-principles', 'mcq', 'With regular dosing at a constant rate, steady-state plasma concentration is reached after approximately how many half-lives?', '["4 to 5 half-lives", "1 half-life", "2 half-lives", "10 half-lives", "7 to 8 half-lives"]'::jsonb, '4 to 5 half-lives', '[]'::jsonb, 'Accumulation follows first-order kinetics: 50% of steady state after 1 half-life, 75% after 2, about 94% after 4 and 97% after 5. So a drug is considered at steady state after 4 to 5 half-lives, whatever the dose. The same time is needed for it to be eliminated after stopping.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-gp-004', 'pharm-general-principles', 'mcq', 'A drug binds a receptor but produces only a submaximal response even when every receptor is occupied. What is it?', '["Partial agonist", "Full agonist", "Competitive antagonist", "Inverse agonist", "Non-competitive antagonist"]'::jsonb, 'Partial agonist', '[]'::jsonb, 'A partial agonist has affinity for the receptor but lower intrinsic efficacy than a full agonist, so its maximum effect is smaller even at full occupancy. A competitive antagonist has affinity but zero efficacy; an inverse agonist reduces the receptor''s baseline activity.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-gp-005', 'pharm-general-principles', 'saq', 'Which family of liver enzymes carries out most phase I drug metabolism?', '[]'::jsonb, 'Cytochrome P450', '["CYP450", "CYP", "P450", "Cytochrome P450 enzymes"]'::jsonb, 'The cytochrome P450 (CYP) mixed-function oxidases, especially CYP3A4 and CYP2D6, perform most phase I reactions (oxidation, reduction, hydrolysis). Many drug interactions come from induction or inhibition of these enzymes.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-gp-006', 'pharm-general-principles', 'mcq', 'A drug with a very large volume of distribution is most likely to be:', '["Extensively distributed into the tissues", "Confined to the plasma", "Highly bound to plasma albumin", "Rapidly excreted unchanged in the urine", "Unable to cross cell membranes"]'::jsonb, 'Extensively distributed into the tissues', '[]'::jsonb, 'Volume of distribution relates the amount of drug in the body to its plasma concentration. A large value means little drug stays in the plasma because it has moved into tissues (for example lipid-soluble drugs such as chloroquine or digoxin). Drugs confined to plasma or tightly bound to albumin have a small volume of distribution.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-gp-007', 'pharm-general-principles', 'saq', 'In which order of kinetics is a constant amount of drug, not a constant fraction, eliminated per unit time?', '[]'::jsonb, 'Zero-order', '["Zero order", "Zero-order kinetics", "Zero order kinetics", "Saturation kinetics"]'::jsonb, 'In zero-order (saturation) kinetics the eliminating enzymes are saturated, so the same amount is removed each hour whatever the concentration. Alcohol, phenytoin and high-dose aspirin behave this way, which is why small dose increases can cause toxicity. Most drugs follow first-order kinetics, where a constant fraction is eliminated.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-gp-008', 'pharm-general-principles', 'mcq', 'Which term describes the maximum response a drug can produce, however large the dose?', '["Efficacy", "Potency", "Affinity", "Selectivity", "Bioavailability"]'::jsonb, 'Efficacy', '[]'::jsonb, 'Efficacy (Emax) is the greatest effect a drug can achieve. Potency is about how much drug is needed for a given effect (EC50), and affinity about how tightly it binds its receptor. A drug can be very potent yet have low efficacy, as partial agonists do.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-gp-009', 'pharm-general-principles', 'mcq', 'The therapeutic index of a drug is the ratio of:', '["The toxic dose (TD50) to the effective dose (ED50)", "The effective dose (ED50) to the toxic dose (TD50)", "Peak to trough plasma concentration", "Bound to unbound drug in plasma", "Clearance to volume of distribution"]'::jsonb, 'The toxic dose (TD50) to the effective dose (ED50)', '[]'::jsonb, 'Therapeutic index = TD50 / ED50. A high value means a wide margin between the dose that works and the dose that harms. Drugs with a low index, such as digoxin, lithium, warfarin and theophylline, need careful dosing and often monitoring of plasma levels.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-gp-010', 'pharm-general-principles', 'saq', 'What is the most common phase II (conjugation) reaction in human drug metabolism?', '[]'::jsonb, 'Glucuronidation', '["Glucuronide conjugation", "Conjugation with glucuronic acid", "Glucuronic acid conjugation"]'::jsonb, 'Phase II reactions attach a polar group so the drug can be excreted in urine or bile. Glucuronidation, carried out by UDP-glucuronosyltransferases, is the most common. Newborns have low activity of this enzyme, which is why chloramphenicol can cause grey baby syndrome.', '', 'seed')
insert into public.topics (id, unit_id, name, sort_order) values ('pharm-autonomic', 'pharmacology', 'Autonomic nervous system', 1)
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-ans-001', 'pharm-autonomic', 'mcq', 'What is the mechanism of action of atropine?', '["Muscarinic receptor antagonist", "Nicotinic receptor antagonist", "Acetylcholinesterase inhibitor", "Beta-adrenoceptor agonist", "Alpha-adrenoceptor antagonist"]'::jsonb, 'Muscarinic receptor antagonist', '[]'::jsonb, 'Atropine competitively blocks muscarinic acetylcholine receptors, producing tachycardia, dry mouth, mydriasis and reduced gut motility. It has little effect at nicotinic receptors, which is why it does not cause muscle paralysis.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-ans-002', 'pharm-autonomic', 'saq', 'Which drug is the first-line treatment for anaphylaxis?', '[]'::jsonb, 'Adrenaline', '["Epinephrine", "Intramuscular adrenaline", "IM adrenaline", "IM epinephrine"]'::jsonb, 'Intramuscular adrenaline (epinephrine) is first line. Alpha-1 stimulation reverses vasodilation and oedema, beta-1 supports cardiac output and beta-2 relieves bronchospasm and stabilises mast cells. Antihistamines and steroids are only adjuncts.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-ans-003', 'pharm-autonomic', 'mcq', 'Which of these is a short-acting selective beta-2 agonist used to relieve acute asthma?', '["Salbutamol", "Propranolol", "Atenolol", "Ipratropium", "Montelukast"]'::jsonb, 'Salbutamol', '[]'::jsonb, 'Salbutamol stimulates beta-2 receptors on bronchial smooth muscle, raising cAMP and causing rapid bronchodilation. Propranolol and atenolol are beta-blockers (propranolol can worsen asthma); ipratropium bronchodilates by blocking muscarinic receptors, not by beta-2 agonism.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-ans-004', 'pharm-autonomic', 'saq', 'Which neurotransmitter is released by all preganglionic autonomic neurons?', '[]'::jsonb, 'Acetylcholine', '["ACh"]'::jsonb, 'Both sympathetic and parasympathetic preganglionic fibres release acetylcholine onto nicotinic receptors in the ganglia. The divisions differ at the postganglionic synapse: mostly noradrenaline for sympathetic, acetylcholine for parasympathetic.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-ans-005', 'pharm-autonomic', 'mcq', 'How does neostigmine produce its effects?', '["It inhibits acetylcholinesterase", "It blocks muscarinic receptors", "It directly activates nicotinic receptors", "It blocks acetylcholine release", "It inhibits choline acetyltransferase"]'::jsonb, 'It inhibits acetylcholinesterase', '[]'::jsonb, 'Neostigmine reversibly inhibits acetylcholinesterase, so acetylcholine accumulates at the synapse. That is why it is used in myasthenia gravis and to reverse non-depolarising neuromuscular blockers. It is not a receptor agonist itself.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-ans-006', 'pharm-autonomic', 'mcq', 'Which of these beta-blockers is non-selective and should be avoided in asthma?', '["Propranolol", "Atenolol", "Bisoprolol", "Metoprolol", "Nebivolol"]'::jsonb, 'Propranolol', '[]'::jsonb, 'Propranolol blocks beta-1 and beta-2 receptors. Blocking beta-2 in the airways can trigger severe bronchospasm in asthma. Atenolol, bisoprolol, metoprolol and nebivolol are relatively beta-1 (cardio) selective, although even these are used with caution.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-ans-007', 'pharm-autonomic', 'mcq', 'Phenylephrine acts mainly by stimulating which receptor?', '["Alpha-1 adrenoceptors", "Alpha-2 adrenoceptors", "Beta-1 adrenoceptors", "Beta-2 adrenoceptors", "Muscarinic M3 receptors"]'::jsonb, 'Alpha-1 adrenoceptors', '[]'::jsonb, 'Phenylephrine is a selective alpha-1 agonist. It constricts blood vessels, which is why it is used as a nasal decongestant, to raise blood pressure, and to dilate the pupil. It has little effect on beta receptors, so it does not directly increase heart rate.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-ans-008', 'pharm-autonomic', 'saq', 'Which drug is given in organophosphate poisoning to block the muscarinic effects of excess acetylcholine?', '[]'::jsonb, 'Atropine', '[]'::jsonb, 'Organophosphates irreversibly inhibit acetylcholinesterase, so acetylcholine accumulates. Atropine blocks muscarinic receptors and reverses the bradycardia, bronchial secretions and bronchospasm. Pralidoxime is added to reactivate the enzyme, but it does not block the receptors itself.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-ans-009', 'pharm-autonomic', 'mcq', 'Pilocarpine lowers intraocular pressure in glaucoma because it is a:', '["Muscarinic agonist", "Muscarinic antagonist", "Beta-blocker", "Carbonic anhydrase inhibitor", "Alpha-2 agonist"]'::jsonb, 'Muscarinic agonist', '[]'::jsonb, 'Pilocarpine stimulates muscarinic M3 receptors, contracting the ciliary muscle and the sphincter of the pupil. This opens the trabecular meshwork and improves drainage of aqueous humour. Muscarinic antagonists such as atropine do the opposite and can precipitate angle-closure glaucoma.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-ans-010', 'pharm-autonomic', 'saq', 'Which enzyme breaks down acetylcholine in the synaptic cleft?', '[]'::jsonb, 'Acetylcholinesterase', '["AChE", "Cholinesterase", "Acetyl cholinesterase"]'::jsonb, 'Acetylcholinesterase rapidly hydrolyses acetylcholine into choline and acetate, ending its action. Drugs that inhibit it, such as neostigmine and donepezil, prolong the action of acetylcholine.', '', 'seed')
insert into public.topics (id, unit_id, name, sort_order) values ('pharm-cardiovascular', 'pharmacology', 'Cardiovascular drugs', 2)
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cvs-001', 'pharm-cardiovascular', 'mcq', 'A persistent dry cough is a characteristic side effect of which drug class?', '["ACE inhibitors", "Calcium channel blockers", "Thiazide diuretics", "Beta-blockers", "Loop diuretics"]'::jsonb, 'ACE inhibitors', '[]'::jsonb, 'ACE also breaks down bradykinin. Inhibiting it (for example with enalapril) lets bradykinin accumulate in the airways, causing a dry cough in roughly 10% of patients. Switching to an angiotensin receptor blocker such as losartan avoids this.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cvs-002', 'pharm-cardiovascular', 'saq', 'Which vitamin is given to reverse the anticoagulant effect of warfarin?', '[]'::jsonb, 'Vitamin K', '["Phytomenadione", "Vitamin K1", "Phytonadione"]'::jsonb, 'Warfarin blocks vitamin K epoxide reductase, so the liver cannot activate clotting factors II, VII, IX and X. Giving vitamin K (phytomenadione) restores their synthesis over hours; for major bleeding, prothrombin complex concentrate is added for an immediate effect.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cvs-003', 'pharm-cardiovascular', 'mcq', 'Furosemide acts on which part of the nephron?', '["Thick ascending limb of the loop of Henle", "Proximal convoluted tubule", "Distal convoluted tubule", "Collecting duct", "Glomerulus"]'::jsonb, 'Thick ascending limb of the loop of Henle', '[]'::jsonb, 'Loop diuretics block the Na+/K+/2Cl- cotransporter (NKCC2) in the thick ascending limb, giving a powerful diuresis. Thiazides act on the distal convoluted tubule, and potassium-sparing diuretics such as spironolactone on the collecting duct.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cvs-004', 'pharm-cardiovascular', 'mcq', 'Statins lower cholesterol by inhibiting which enzyme?', '["HMG-CoA reductase", "Lipoprotein lipase", "Cholesterol ester transfer protein", "Acetyl-CoA carboxylase", "Squalene epoxidase"]'::jsonb, 'HMG-CoA reductase', '[]'::jsonb, 'HMG-CoA reductase is the rate-limiting enzyme of hepatic cholesterol synthesis. Inhibiting it makes hepatocytes express more LDL receptors, which clears LDL from the blood. Muscle pain and raised liver enzymes are the main adverse effects.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cvs-005', 'pharm-cardiovascular', 'saq', 'Which electrolyte disturbance most increases the risk of digoxin toxicity?', '[]'::jsonb, 'Hypokalaemia', '["Hypokalemia", "Low potassium", "Low serum potassium"]'::jsonb, 'Digoxin competes with potassium for its binding site on the Na+/K+-ATPase. When potassium is low, more digoxin binds and toxicity (arrhythmias, nausea, visual disturbance) occurs at normal doses. This matters when digoxin is combined with loop or thiazide diuretics.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cvs-006', 'pharm-cardiovascular', 'mcq', 'Amlodipine lowers blood pressure by blocking:', '["L-type calcium channels", "Beta-1 adrenoceptors", "Angiotensin II receptors", "The sodium-potassium ATPase", "Aldosterone receptors"]'::jsonb, 'L-type calcium channels', '[]'::jsonb, 'Amlodipine is a dihydropyridine calcium channel blocker. Blocking L-type calcium channels in vascular smooth muscle causes arterial vasodilation and lowers blood pressure. Ankle swelling, flushing and headache are its typical side effects.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cvs-007', 'pharm-cardiovascular', 'saq', 'What is the antidote for heparin overdose?', '[]'::jsonb, 'Protamine sulfate', '["Protamine", "Protamine sulphate"]'::jsonb, 'Protamine is a positively charged protein that binds the negatively charged heparin and neutralises it within minutes. It fully reverses unfractionated heparin but only partly reverses low-molecular-weight heparins.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cvs-008', 'pharm-cardiovascular', 'mcq', 'Which diuretic is a competitive aldosterone antagonist and can cause hyperkalaemia?', '["Spironolactone", "Furosemide", "Hydrochlorothiazide", "Mannitol", "Acetazolamide"]'::jsonb, 'Spironolactone', '[]'::jsonb, 'Spironolactone blocks aldosterone receptors in the collecting duct, so sodium is lost and potassium is retained. It can therefore cause hyperkalaemia, and gynaecomastia through its anti-androgen effect. Furosemide and thiazides cause potassium loss instead.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cvs-009', 'pharm-cardiovascular', 'mcq', 'Glyceryl trinitrate relieves angina mainly by:', '["Dilating veins, which reduces preload", "Increasing the heart rate", "Blocking beta-1 adrenoceptors", "Inhibiting platelet aggregation", "Increasing myocardial contractility"]'::jsonb, 'Dilating veins, which reduces preload', '[]'::jsonb, 'Nitrates release nitric oxide, which relaxes vascular smooth muscle, mostly in veins. Less blood returns to the heart, so preload, wall tension and oxygen demand fall. It is given under the tongue to avoid first-pass metabolism.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cvs-010', 'pharm-cardiovascular', 'saq', 'Clopidogrel prevents platelet aggregation by blocking which receptor?', '[]'::jsonb, 'P2Y12', '["P2Y12 receptor", "ADP receptor", "P2Y12 ADP receptor", "ADP P2Y12 receptor"]'::jsonb, 'Clopidogrel is a prodrug whose active metabolite irreversibly blocks the P2Y12 ADP receptor on platelets, so ADP can no longer activate them. Aspirin works differently, by inhibiting cyclo-oxygenase and thromboxane A2 production.', '', 'seed')
insert into public.topics (id, unit_id, name, sort_order) values ('pharm-cns', 'pharmacology', 'Central nervous system drugs', 3)
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cns-001', 'pharm-cns', 'mcq', 'How do benzodiazepines enhance the effect of GABA at the GABA-A receptor?', '["They increase the frequency of chloride channel opening", "They increase the duration of chloride channel opening", "They open the chloride channel directly without GABA", "They block GABA reuptake", "They block NMDA glutamate receptors"]'::jsonb, 'They increase the frequency of chloride channel opening', '[]'::jsonb, 'Benzodiazepines bind an allosteric site and make the channel open more often when GABA is present. Barbiturates instead prolong the duration of opening and at high doses open the channel directly, which is why they are more dangerous in overdose.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cns-002', 'pharm-cns', 'saq', 'What is the specific antidote for benzodiazepine overdose?', '[]'::jsonb, 'Flumazenil', '[]'::jsonb, 'Flumazenil is a competitive antagonist at the benzodiazepine site of the GABA-A receptor. It has a short half-life, so sedation can return, and it may provoke seizures in patients dependent on benzodiazepines.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cns-003', 'pharm-cns', 'mcq', 'Why is levodopa combined with carbidopa in Parkinson''s disease?', '["To reduce peripheral conversion of levodopa to dopamine", "To increase dopamine receptor sensitivity", "To inhibit dopamine breakdown in the brain", "To block peripheral dopamine receptors", "To increase absorption of levodopa from the gut"]'::jsonb, 'To reduce peripheral conversion of levodopa to dopamine', '[]'::jsonb, 'Carbidopa inhibits DOPA decarboxylase outside the brain and does not cross the blood-brain barrier. More levodopa therefore reaches the brain, and peripheral dopamine effects such as nausea and hypotension are reduced.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cns-004', 'pharm-cns', 'mcq', 'Fluoxetine belongs to which class of antidepressants?', '["Selective serotonin reuptake inhibitors", "Tricyclic antidepressants", "Monoamine oxidase inhibitors", "Serotonin-noradrenaline reuptake inhibitors", "Atypical antipsychotics"]'::jsonb, 'Selective serotonin reuptake inhibitors', '[]'::jsonb, 'Fluoxetine selectively blocks the serotonin transporter (SERT), raising synaptic serotonin. SSRIs are first line for depression because they are safer in overdose than tricyclics and need no dietary restrictions, unlike MAO inhibitors.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cns-005', 'pharm-cns', 'saq', 'What is the specific antidote for opioid overdose?', '[]'::jsonb, 'Naloxone', '[]'::jsonb, 'Naloxone is a competitive antagonist at mu-opioid receptors and rapidly reverses respiratory depression. Its half-life is shorter than that of most opioids, so repeated doses or an infusion may be needed.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cns-006', 'pharm-cns', 'mcq', 'Which adverse effect is most characteristic of typical antipsychotics such as haloperidol?', '["Extrapyramidal side effects", "Agranulocytosis", "Hepatic necrosis", "Nephrogenic diabetes insipidus", "Gingival hyperplasia"]'::jsonb, 'Extrapyramidal side effects', '[]'::jsonb, 'Haloperidol strongly blocks dopamine D2 receptors in the nigrostriatal pathway, causing dystonia, parkinsonism, akathisia and later tardive dyskinesia. Agranulocytosis is linked to clozapine, nephrogenic diabetes insipidus to lithium and gingival hyperplasia to phenytoin.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cns-007', 'pharm-cns', 'saq', 'Which mood stabiliser has a narrow therapeutic range and needs regular monitoring of its plasma level?', '[]'::jsonb, 'Lithium', '["Lithium carbonate"]'::jsonb, 'Lithium is effective in bipolar disorder but toxic just above its therapeutic range, causing tremor, confusion and kidney damage. Levels rise with dehydration, NSAIDs, ACE inhibitors and thiazides. Thyroid and renal function are also checked regularly.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cns-008', 'pharm-cns', 'mcq', 'Phenytoin controls seizures mainly by blocking:', '["Voltage-gated sodium channels", "T-type calcium channels", "GABA transaminase", "NMDA receptors", "Potassium channels"]'::jsonb, 'Voltage-gated sodium channels', '[]'::jsonb, 'Phenytoin holds voltage-gated sodium channels in their inactivated state, which stops neurons firing at high frequency. T-type calcium channels are the target of ethosuximide, and GABA transaminase the target of vigabatrin.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cns-009', 'pharm-cns', 'mcq', 'Which drug is first-line for absence seizures?', '["Ethosuximide", "Phenytoin", "Carbamazepine", "Phenobarbital", "Gabapentin"]'::jsonb, 'Ethosuximide', '[]'::jsonb, 'Ethosuximide blocks T-type calcium channels in thalamic neurons, which generate the 3 Hz spike-and-wave pattern of absence seizures. Sodium valproate is the main alternative. Phenytoin and carbamazepine can make absence seizures worse.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-cns-010', 'pharm-cns', 'saq', 'Which inhaled anaesthetic gas is commonly called "laughing gas"?', '[]'::jsonb, 'Nitrous oxide', '["N2O"]'::jsonb, 'Nitrous oxide is a weak anaesthetic but a good analgesic with rapid onset and recovery. It is used with oxygen for pain relief in labour and minor procedures. Long exposure can inactivate vitamin B12.', '', 'seed')
insert into public.topics (id, unit_id, name, sort_order) values ('pharm-antimicrobials', 'pharmacology', 'Antimicrobials', 4)
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-abx-001', 'pharm-antimicrobials', 'mcq', 'How do penicillins kill bacteria?', '["They inhibit cell wall synthesis", "They inhibit protein synthesis at the 30S ribosome", "They inhibit DNA gyrase", "They inhibit folate synthesis", "They disrupt the cell membrane"]'::jsonb, 'They inhibit cell wall synthesis', '[]'::jsonb, 'Penicillins are beta-lactams: they bind penicillin-binding proteins and block the cross-linking of peptidoglycan, so the cell wall fails and the bacterium lyses. Aminoglycosides and tetracyclines act on the 30S ribosome, quinolones on DNA gyrase and sulfonamides on folate synthesis.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-abx-002', 'pharm-antimicrobials', 'mcq', 'Which pair of toxicities is characteristic of aminoglycosides such as gentamicin?', '["Nephrotoxicity and ototoxicity", "Hepatotoxicity and optic neuritis", "Tendon rupture and QT prolongation", "Bone marrow suppression and grey baby syndrome", "Peripheral neuropathy and hepatitis"]'::jsonb, 'Nephrotoxicity and ototoxicity', '[]'::jsonb, 'Aminoglycosides accumulate in renal tubular cells and in the inner ear, so levels are monitored. Tendon rupture and QT prolongation belong to fluoroquinolones; marrow suppression and grey baby syndrome to chloramphenicol.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-abx-003', 'pharm-antimicrobials', 'saq', 'Which antituberculous drug turns urine and other body fluids orange-red?', '[]'::jsonb, 'Rifampicin', '["Rifampin"]'::jsonb, 'Rifampicin (rifampin) harmlessly colours urine, tears and sweat orange-red; patients should be warned. It inhibits bacterial DNA-dependent RNA polymerase and is a strong inducer of cytochrome P450 enzymes, causing many drug interactions.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-abx-004', 'pharm-antimicrobials', 'mcq', 'Ciprofloxacin and other fluoroquinolones inhibit which bacterial enzyme?', '["DNA gyrase", "Transpeptidase", "Dihydrofolate reductase", "RNA polymerase", "Beta-lactamase"]'::jsonb, 'DNA gyrase', '[]'::jsonb, 'Fluoroquinolones inhibit DNA gyrase (topoisomerase II) and topoisomerase IV, preventing DNA replication. Transpeptidase is the beta-lactam target, dihydrofolate reductase the trimethoprim target and RNA polymerase the rifampicin target.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-abx-005', 'pharm-antimicrobials', 'saq', 'Which vitamin is given with isoniazid to prevent peripheral neuropathy?', '[]'::jsonb, 'Pyridoxine', '["Vitamin B6", "B6", "Pyridoxine (vitamin B6)"]'::jsonb, 'Isoniazid interferes with pyridoxine (vitamin B6) metabolism, and the resulting deficiency causes peripheral neuropathy. A small daily dose of pyridoxine prevents it, especially in malnourished, pregnant, diabetic or alcohol-dependent patients.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-abx-006', 'pharm-antimicrobials', 'mcq', 'Which antibiotic class can permanently discolour teeth and is avoided in children under 8?', '["Tetracyclines", "Macrolides", "Penicillins", "Cephalosporins", "Aminoglycosides"]'::jsonb, 'Tetracyclines', '[]'::jsonb, 'Tetracyclines bind calcium and are deposited in growing teeth and bones, causing permanent staining and enamel defects. For the same reason they are avoided in pregnancy. Their absorption is also reduced by milk, antacids and iron.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-abx-007', 'pharm-antimicrobials', 'saq', 'Which antibiotic is the usual drug of choice for serious MRSA infections?', '[]'::jsonb, 'Vancomycin', '[]'::jsonb, 'MRSA has an altered penicillin-binding protein, so it resists all standard beta-lactams. Vancomycin, a glycopeptide, blocks cell wall synthesis at a different step by binding the D-alanyl-D-alanine end of the peptidoglycan precursor.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-abx-008', 'pharm-antimicrobials', 'mcq', 'Metronidazole is active mainly against:', '["Anaerobic bacteria and protozoa", "Aerobic Gram-negative bacilli only", "Mycobacteria", "Fungi", "Viruses"]'::jsonb, 'Anaerobic bacteria and protozoa', '[]'::jsonb, 'Metronidazole is activated only in organisms with anaerobic metabolism, where its reduced form damages DNA. It treats anaerobic infections, Clostridioides difficile, Trichomonas, Giardia and amoebiasis. Patients should avoid alcohol because of a disulfiram-like reaction.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-abx-009', 'pharm-antimicrobials', 'mcq', 'Aciclovir is used to treat infections caused by:', '["Herpes simplex virus", "Human immunodeficiency virus", "Influenza virus", "Hepatitis C virus", "Rotavirus"]'::jsonb, 'Herpes simplex virus', '[]'::jsonb, 'Aciclovir is activated by a thymidine kinase made by herpes viruses, then blocks viral DNA polymerase. It is used for herpes simplex and varicella-zoster infections. Because uninfected cells do not activate it, it is selective and relatively safe.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-abx-010', 'pharm-antimicrobials', 'saq', 'Which intravenous antifungal, used for severe systemic infections, binds ergosterol and forms pores in the fungal cell membrane?', '[]'::jsonb, 'Amphotericin B', '["Amphotericin", "Liposomal amphotericin B", "Amphotericin-B"]'::jsonb, 'Amphotericin B binds ergosterol in the fungal membrane and creates pores that let ions leak out, killing the cell. Its main toxicity is to the kidney, with infusion reactions also common. Azoles act differently, by blocking ergosterol synthesis.', '', 'seed')
insert into public.topics (id, unit_id, name, sort_order) values ('pharm-analgesics', 'pharmacology', 'Analgesics and anti-inflammatory drugs', 5)
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-nsaid-001', 'pharm-analgesics', 'mcq', 'What is the mechanism of action of aspirin?', '["Irreversible inhibition of cyclo-oxygenase", "Reversible inhibition of cyclo-oxygenase", "Inhibition of phospholipase A2", "Blockade of prostaglandin receptors", "Inhibition of lipoxygenase"]'::jsonb, 'Irreversible inhibition of cyclo-oxygenase', '[]'::jsonb, 'Aspirin acetylates COX-1 and COX-2 irreversibly. Platelets have no nucleus and cannot make new enzyme, so the antiplatelet effect lasts the life of the platelet (7 to 10 days). Other NSAIDs such as ibuprofen inhibit COX reversibly; corticosteroids are the drugs that reduce phospholipase A2 activity.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-nsaid-002', 'pharm-analgesics', 'saq', 'What is the antidote for paracetamol (acetaminophen) overdose?', '[]'::jsonb, 'N-acetylcysteine', '["Acetylcysteine", "NAC", "N acetyl cysteine"]'::jsonb, 'In overdose the toxic metabolite NAPQI depletes hepatic glutathione and causes liver necrosis. N-acetylcysteine replenishes glutathione and is most effective when given within 8 hours of ingestion.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-nsaid-003', 'pharm-analgesics', 'mcq', 'Tolerance does NOT develop to which effect of morphine?', '["Constipation", "Analgesia", "Euphoria", "Respiratory depression", "Sedation"]'::jsonb, 'Constipation', '[]'::jsonb, 'With repeated dosing, tolerance develops to analgesia, euphoria, sedation and respiratory depression, but not to constipation or miosis. That is why patients on long-term opioids need a regular laxative.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-nsaid-004', 'pharm-analgesics', 'mcq', 'Which is the most common serious adverse effect of long-term non-selective NSAID use?', '["Peptic ulceration and gastrointestinal bleeding", "Hepatic necrosis", "Peripheral neuropathy", "Pulmonary fibrosis", "Hypoglycaemia"]'::jsonb, 'Peptic ulceration and gastrointestinal bleeding', '[]'::jsonb, 'Inhibiting COX-1 removes the prostaglandins that protect the gastric mucosa (mucus, bicarbonate, blood flow), leading to ulcers and bleeding. NSAIDs can also impair renal function; a proton pump inhibitor is often co-prescribed for gastric protection.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-nsaid-005', 'pharm-analgesics', 'mcq', 'Which of these drugs is a selective COX-2 inhibitor?', '["Celecoxib", "Ibuprofen", "Naproxen", "Indomethacin", "Aspirin"]'::jsonb, 'Celecoxib', '[]'::jsonb, 'Celecoxib spares COX-1, so it causes less gastric ulceration than non-selective NSAIDs, at the cost of a higher cardiovascular risk. Ibuprofen, naproxen and indomethacin inhibit both COX-1 and COX-2.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-nsaid-006', 'pharm-analgesics', 'mcq', 'Which organ is mainly damaged in paracetamol (acetaminophen) overdose?', '["Liver", "Kidney", "Heart", "Lungs", "Pancreas"]'::jsonb, 'Liver', '[]'::jsonb, 'In overdose the normal conjugation pathways are saturated and more paracetamol is converted to the toxic metabolite NAPQI. Once glutathione is used up, NAPQI destroys liver cells. Liver damage appears after 2 to 3 days, so early treatment with N-acetylcysteine is vital.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-nsaid-007', 'pharm-analgesics', 'saq', 'Which drug lowers uric acid in chronic gout by inhibiting xanthine oxidase?', '[]'::jsonb, 'Allopurinol', '["Febuxostat"]'::jsonb, 'Allopurinol inhibits xanthine oxidase, the enzyme that makes uric acid, and is the first-line drug to prevent gout attacks (febuxostat is a newer drug with the same target). It is not started during an acute attack, and it increases the toxicity of azathioprine.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-nsaid-008', 'pharm-analgesics', 'mcq', 'Aspirin is avoided in children with a viral illness because of the risk of:', '["Reye''s syndrome", "Grey baby syndrome", "Kernicterus", "Stevens-Johnson syndrome", "Red man syndrome"]'::jsonb, 'Reye''s syndrome', '[]'::jsonb, 'Reye''s syndrome is a rare but serious combination of liver failure and brain swelling linked to aspirin use in children with viral infections such as influenza or chickenpox. Paracetamol is used instead. Grey baby syndrome is caused by chloramphenicol and red man syndrome by vancomycin.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-nsaid-009', 'pharm-analgesics', 'mcq', 'Which of these is a weak opioid often used for moderate pain?', '["Codeine", "Morphine", "Fentanyl", "Naloxone", "Diamorphine"]'::jsonb, 'Codeine', '[]'::jsonb, 'Codeine is a weak opioid and a prodrug: part of it is converted to morphine by CYP2D6, so its effect varies between people. Morphine, fentanyl and diamorphine are strong opioids. Naloxone is an opioid antagonist, not an analgesic.', '', 'seed')
insert into public.questions (id, topic_id, type, text, options, answer, alt_answers, explanation, image_path, source) values
  ('pharm-nsaid-010', 'pharm-analgesics', 'saq', 'Which sign in the pupils is characteristic of opioid overdose?', '[]'::jsonb, 'Pinpoint pupils', '["Miosis", "Constricted pupils", "Pin point pupils", "Small pupils", "Pin-point pupils"]'::jsonb, 'Opioids stimulate the parasympathetic supply to the pupil, causing marked constriction (miosis). Together with a low respiratory rate and reduced consciousness it forms the classic triad of opioid overdose. Tolerance does not develop to this effect.', '', 'seed')
